"""Admission compiler: cut certificates, plans, and plan validation.

Everything here is exact integer arithmetic.  A plan is a weighted logical
forest over the participants plus compressed serial unicast routes for the
logical edges.  Ordinary (non participant) forwarding vertices only ever
appear in the middle of a walk; they never multicast or aggregate, because a
concatenation always charges both children with the full multiplicity.
"""

import random
import time

from miniflow import FlowNet

INF_MARK = 1 << 4000

MAX_TREES = 8192
MAX_ROUTES = 32768
MAX_RECIPE_NODES = 65536


class Job:
    """One recurring allgather compilation problem."""

    def __init__(self, n, links, demands, period, envelope):
        self.n = n
        self.links = links                      # [(u, v, base_capacity)]
        self.demands = dict(demands)            # participant vertex -> r_v
        self.C = sorted(self.demands)
        self.D = sum(self.demands.values())
        self.p = period
        # per direction per period physical budget c_l = p * b_l
        self.c = [period * int(envelope.get(l, 0)) for l in range(len(links))]
        # arc ids: link l direction 0 -> arc 2l (u->v), direction 1 -> 2l+1
        self.arc_u = []
        self.arc_v = []
        self.arc_link = []
        self.arc_dir = []
        for l, (u, v, _cap) in enumerate(links):
            self.arc_u += [u, v]
            self.arc_v += [v, u]
            self.arc_link += [l, l]
            self.arc_dir += [0, 1]
        self.participant = [False] * n
        for v in self.C:
            self.participant[v] = True

    # ---------- helpers ----------
    def fresh_res(self):
        return list(self.c)

    def _allowed(self, u, v):
        """Vertices usable inside a walk from participant u to participant v."""
        ok = [not self.participant[x] for x in range(self.n)]
        ok[u] = True
        ok[v] = True
        return ok

    def arcs_out(self, u, res, allowed):
        out = []
        for aid in range(len(self.arc_u)):
            if self.arc_u[aid] == u and res[aid] > 0 and allowed[self.arc_v[aid]]:
                out.append(aid)
        return out

    def out_bound(self, u, v, res, allowed):
        """Cheap upper bound on how much can travel from u to v."""
        src = 0
        dst = 0
        for aid in range(len(self.arc_u)):
            if res[aid] <= 0:
                continue
            a, b = self.arc_u[aid], self.arc_v[aid]
            if not allowed[a] or not allowed[b]:
                continue
            if a == u:
                src += res[aid]
            if b == v:
                dst += res[aid]
        return src if src < dst else dst

    def hops(self, u, v, res, allowed):
        """Minimum number of physical links from u to v, or None."""
        dist = {u: 0}
        frontier = [u]
        while frontier:
            nxt = []
            for x in frontier:
                for aid in range(len(self.arc_u)):
                    if self.arc_u[aid] != x or res[aid] <= 0:
                        continue
                    y = self.arc_v[aid]
                    if not allowed[y] or y in dist:
                        continue
                    dist[y] = dist[x] + 1
                    if y == v:
                        return dist[y]
                    nxt.append(y)
            frontier = nxt
        return None

    # ---------- augmenting walk push ----------
    def push(self, u, v, res, need, scale, rng=None):
        """Push exactly `need` units u->v if possible (integral, unicast).

        Returns (pushed, [(arc_tuple, amount), ...]) mutating `res`.
        """
        allowed = self._allowed(u, v)
        out = []
        total = 0
        guard = 0
        while total < need and guard < 4096:
            guard += 1
            path = self._dijkstra(u, v, res, allowed, need - total, rng)
            if path is None:
                break
            room = need - total
            for aid in path:
                if res[aid] < room:
                    room = res[aid]
            for aid in path:
                res[aid] -= room
            out.append((tuple(path), room))
            total += room
        return total, out

    def _dijkstra(self, u, v, res, allowed, need, rng):
        """Shortest/scarcity-aware residual path, or None when unreachable."""
        n = self.n
        best = [None] * n
        done = [False] * n
        cost = [INF_MARK] * n
        prev = [None] * n
        cost[u] = 0
        for _ in range(n):
            x = -1
            bc = None
            for i in range(n):
                if not done[i] and (bc is None or cost[i] < bc):
                    bc = cost[i]
                    x = i
            if x < 0 or bc >= INF_MARK:
                break
            if x == v:
                done[x] = True
                break
            done[x] = True
            for aid in range(len(self.arc_u)):
                if self.arc_u[aid] != x or res[aid] <= 0:
                    continue
                y = self.arc_v[aid]
                if not allowed[y] or done[y]:
                    continue
                w = 1 + need // res[aid]
                if rng is not None and rng.random() < 0.25:
                    w += 1
                nc = bc + w
                if nc < cost[y]:
                    cost[y] = nc
                    prev[y] = aid
                    best[y] = x
        if cost[v] >= INF_MARK:
            return None
        path = []
        node = v
        while node != u:
            aid = prev[node]
            path.append(aid)
            node = self.arc_u[aid]
        path.reverse()
        return path

    # ---------- recipe packing ----------
    def make_recipes(self, walks):
        """Build the serial-route circuit for a set of arc walks.

        Returns (nodes, {walk: node_id}) where nodes is the recipe array.
        Prefix sharing keeps the circuit inside its published size budget.
        """
        nodes = []
        memo = {}

        def walk_end(pos, aid):
            return self.arc_v[aid] if pos is None else nodes[pos][0]

        for walk in sorted(walks, key=lambda w: (len(w), w)):
            if walk in memo:
                continue
            # longest already-built prefix
            start = None
            k = 0
            for cut in range(len(walk) - 1, 0, -1):
                pre = walk[:cut]
                if pre in memo:
                    start = memo[pre]
                    k = cut
                    break
            if start is None:
                aid = walk[0]
                nodes.append((self.arc_v[aid], [0, self.arc_link[aid], self.arc_dir[aid]]))
                start = len(nodes) - 1
                memo[walk[:1]] = start
                k = 1
            for idx in range(k, len(walk)):
                aid = walk[idx]
                nodes.append((self.arc_v[aid], [0, self.arc_link[aid], self.arc_dir[aid]]))
                leaf = len(nodes) - 1
                left_end = nodes[start][0]
                assert left_end == self.arc_u[aid]
                nodes.append((self.arc_v[aid], [1, start, leaf]))
                start = len(nodes) - 1
                memo[walk[:idx + 1]] = start
            memo[walk] = start
        array = [entry[1] for entry in nodes]
        return array, memo


def find_deficient_cut(job):
    """Return a vertex set S with cut capacity strictly below internal demand.

    Minimises cap(S) - demand(S) over every set that holds at least one but
    not all participants, using one constrained minimum cut per participant
    pair.  Returns None when no strict certificate exists.
    """
    C = job.C
    D = job.D
    if len(C) < 2:
        return None
    n = job.n
    ss, tt = n, n + 1
    base = D + 1
    for l in job.c:
        base += l
    BIG = base * (D + 1) + 1
    best = None
    for a in C:
        for b in C:
            if a == b:
                continue
            net = FlowNet(n + 2)
            arcs = []
            for l, (u, v, _cap) in enumerate(job.links):
                w = job.c[l]
                if w > 0:
                    net.add(u, v, w)
                    net.add(v, u, w)
            for x in C:
                r = job.demands[x]
                if r > 0:
                    net.add(ss, x, r)
            net.add(ss, a, BIG)
            net.add(b, tt, BIG)
            val = net.maxflow(ss, tt, stop=D)
            if val < D:
                side = net.source_side(ss)
                S = sorted(x for x in range(n) if x in side and x != ss and x != tt)
                return S
            if best is None:
                side = net.source_side(ss)
                best = sorted(x for x in range(n) if x in side and x != ss and x != tt)
    return None


def cut_value(job, S):
    inside = set(S)
    cap = 0
    dem = 0
    for l, (u, v, _c) in enumerate(job.links):
        if (u in inside) != (v in inside):
            cap += job.c[l]
    for x in job.C:
        if x in inside:
            dem += job.demands[x]
    return cap, dem


# --------------------------------------------------------------------------
# plan construction

def _grow_tree(job, root, rem, res, rng, prefer_root_tail):
    """Build one spanning out-branching on the participants from `root`."""
    C = job.C
    todo = [x for x in C if x != root]
    frontier = [root]
    attached = {root}
    edges = []
    while todo:
        cands = []
        for u in frontier:
            allowed = job._allowed(u, None) if False else None
            for v in todo:
                aw = job._allowed(u, v)
                if not (aw[u] and aw[v]):
                    continue
                ub = job.out_bound(u, v, res, aw)
                if ub <= 0:
                    continue
                h = job.hops(u, v, res, aw)
                if h is None:
                    continue
                cands.append((u, v, ub, h))
        if not cands:
            return None
        keyroot = 0 if prefer_root_tail else 1
        scored = []
        for (u, v, ub, h) in cands:
            isroot = 1 if u == root else 0
            capub = ub if ub < rem else rem
            jitter = rng.random() * 0.5
            scored.append(((0 if isroot == keyroot else 1), -capub, h, jitter, u, v, ub, h))
        scored.sort()
        pick = scored[0]
        u, v = pick[4], pick[5]
        edges.append((u, v))
        frontier.append(v)
        attached.add(v)
        todo.remove(v)
    return edges


def compile_plan(job, budget=18.0, seed=12345):
    """Try hard to build a valid PLAN; return it or None."""
    deadline = time.monotonic() + budget
    C = job.C
    if len(C) < 2 or job.D <= 0:
        return None
    strategies = []
    for attempt in range(48):
        strategies.append((seed + attempt * 7919, attempt % 2 == 0, attempt % 3))
    for (sd, prefer_root_tail, order_mode) in strategies:
        if time.monotonic() > deadline:
            break
        rng = random.Random(sd)
        plan = _one_attempt(job, rng, prefer_root_tail, order_mode, deadline)
        if plan is not None and check_plan(job, plan):
            return plan
    return None


def _one_attempt(job, rng, prefer_root_tail, order_mode, deadline):
    roots = [v for v in job.C if job.demands[v] > 0]
    if order_mode == 0:
        order = sorted(roots, key=lambda v: -job.demands[v])
    elif order_mode == 1:
        order = sorted(roots, key=lambda v: -job.demands[v])
        rng.shuffle(order)
    else:
        order = list(roots)
        rng.shuffle(order)
    res = job.fresh_res()
    trees = []
    route_map = {}        # (u, v, walk) -> total count
    loads = {}
    for root in order:
        rem = job.demands[root]
        while rem > 0:
            if time.monotonic() > deadline:
                return None
            tree = _grow_tree(job, root, rem, res, rng, prefer_root_tail)
            if tree is None:
                return None
            done = False
            for _shrink in range(8):
                snap = list(res)
                w = rem
                ok = True
                commits = []
                # most constrained logical edge first
                scored = []
                for (u, v) in tree:
                    aw = job._allowed(u, v)
                    scored.append((job.out_bound(u, v, res, aw), u, v))
                scored.sort()
                for (_ub, u, v) in scored:
                    pushed, pieces = job.push(u, v, res, w, None, rng)
                    if pushed < w:
                        ok = False
                        w = pushed
                        break
                    commits.append((u, v, pieces))
                if ok and w > 0:
                    for (u, v, pieces) in commits:
                        for (walk, amount) in pieces:
                            key = (u, v, walk)
                            route_map[key] = route_map.get(key, 0) + amount
                            for aid in walk:
                                loads[aid] = loads.get(aid, 0) + amount
                    trees.append((root, w, tree))
                    rem -= w
                    done = True
                    break
                res = snap
                if w <= 0:
                    break
            if not done:
                return None
    if not trees and job.D > 0:
        return None
    # representation
    walks = set(key[2] for key in route_map)
    recipes, memo = job.make_recipes(walks)
    routes = []
    for (u, v, walk), count in sorted(route_map.items()):
        routes.append([u, v, count, memo[walk]])
    tree_records = []
    for (root, count, edges) in trees:
        tree_records.append([root, count, [[u, v] for (u, v) in edges]])
    return {'trees': tree_records, 'routes': routes, 'recipes': recipes}


# --------------------------------------------------------------------------
# plan validation (mirrors the published checker semantics)

def check_plan(job, plan):
    try:
        return _check_plan(job, plan)
    except Exception:
        return False


def _check_plan(job, plan):
    if set(plan) != {'trees', 'routes', 'recipes'}:
        return False
    trees = plan['trees']
    routes = plan['routes']
    recipes = plan['recipes']
    C = job.C
    pc = set(C)
    if len(C) < 2:
        return False
    if len(trees) > MAX_TREES or len(routes) > MAX_ROUTES or len(recipes) > MAX_RECIPE_NODES:
        return False
    D = job.D
    per_root = {v: 0 for v in C}
    L = {}
    m = len(job.links)
    for rec in trees:
        if not isinstance(rec, list) or len(rec) != 3:
            return False
        root, count, edges = rec
        if type(root) is not int or type(count) is not int:
            return False
        if root not in pc or count <= 0 or count > D:
            return False
        if not isinstance(edges, list) or len(edges) != len(C) - 1:
            return False
        seen = set()
        indeg = {}
        adj = {}
        for e in edges:
            if not isinstance(e, list) or len(e) != 2:
                return False
            a, b = e
            if type(a) is not int or type(b) is not int:
                return False
            if a not in pc or b not in pc or a == b:
                return False
            if (a, b) in seen:
                return False
            seen.add((a, b))
            indeg[b] = indeg.get(b, 0) + 1
            adj.setdefault(a, []).append(b)
        if indeg.get(root, 0) != 0:
            return False
        for v in C:
            if v == root:
                continue
            if indeg.get(v, 0) != 1:
                return False
        # reachability
        stack = [root]
        got = {root}
        while stack:
            x = stack.pop()
            for y in adj.get(x, ()):
                if y not in got:
                    got.add(y)
                    stack.append(y)
        if got != pc:
            return False
        per_root[root] += count
        for (a, b) in seen:
            L[(a, b)] = L.get((a, b), 0) + count
    for v in C:
        if per_root[v] != job.demands[v]:
            return False
    # recipes: acyclic, well typed serial walks
    n = job.n
    start = [None] * len(recipes)
    end = [None] * len(recipes)
    seqs = [None] * len(recipes)
    for i, node in enumerate(recipes):
        if not isinstance(node, list) or len(node) != 3:
            return False
        kind = node[0]
        if type(kind) is not int:
            return False
        if kind == 0:
            l, d = node[1], node[2]
            if type(l) is not int or type(d) is not int:
                return False
            if not (0 <= l < m) or d not in (0, 1):
                return False
            u, v, _cap = job.links[l]
            start[i], end[i] = (u, v) if d == 0 else (v, u)
            seqs[i] = [(l, d)]
        elif kind == 1:
            a, b = node[1], node[2]
            if type(a) is not int or type(b) is not int:
                return False
            if not (0 <= a < len(recipes)) or not (0 <= b < len(recipes)):
                return False
            if a >= i or b >= i:      # built forward-referenced-free
                return False
            if seqs[a] is None or seqs[b] is None:
                return False
            if end[a] != start[b]:
                return False
            if end[a] in pc:
                return False
            start[i], end[i] = start[a], end[b]
            seqs[i] = seqs[a] + seqs[b]
        else:
            return False
    # routes
    per_pair = {}
    loads = {}
    for rec in routes:
        if not isinstance(rec, list) or len(rec) != 4:
            return False
        u, v, count, rid = rec
        for x in (u, v, count, rid):
            if type(x) is not int:
                return False
        if u not in pc or v not in pc or u == v:
            return False
        if count < 1 or count > D:
            return False
        if not (0 <= rid < len(recipes)):
            return False
        if start[rid] != u or end[rid] != v:
            return False
        per_pair[(u, v)] = per_pair.get((u, v), 0) + count
        for (l, d) in seqs[rid]:
            loads[(l, d)] = loads.get((l, d), 0) + count
    for pair in set(list(per_pair) + list(L)):
        if per_pair.get(pair, 0) != L.get(pair, 0):
            return False
    for l in range(m):
        for d in (0, 1):
            if loads.get((l, d), 0) > job.c[l]:
                return False
    return True
